//  fonts_base64.js -- Gemeinsames Schriften-Modul fuer jsPDF-Vektor-Export
//  Wedding Story Atelier - alle Generatoren
//
//  Generiert: 2026-04-11
//  Eingebettet: 9 / 9 Schriften  (~3837 KB Base64)
//
//  Verwendung in jedem Generator:
//    <script src="fonts_base64.js"></script>
//    WSA_FONTS.registerWith(pdf);
//    WSA_FONTS.set(pdf, 'CormorantGaramond', 'italic');
// =============================================================================

(function () {

  var DATA = {
    // CormorantGaramond-Light (867 KB)
    'CormorantGaramond-Light': '',

    // CormorantGaramond-Regular (868 KB)
    'CormorantGaramond-Regular': '',

    // CormorantGaramond-SemiBold (868 KB)
    'CormorantGaramond-SemiBold': '',

    // CormorantGaramond-Italic (531 KB)
    'CormorantGaramond-Italic': '',

    // PlayfairDisplay-Bold (252 KB)
    'PlayfairDisplay-Bold': '',

    // PlayfairDisplay-BoldItalic (232 KB)
    'PlayfairDisplay-BoldItalic': '',

    // DMSans-Light (73 KB)
    'DMSans-Light': '',

    // DMSans-Regular (73 KB)
    'DMSans-Regular': '',

    // DMSans-Medium (73 KB)
    'DMSans-Medium': '',
      'PinyonScript-Regular': '',
  };

  var MAP = [
    { key: 'CormorantGaramond-Light', name: 'CormorantGaramond', style: 'light' },
    { key: 'CormorantGaramond-Regular', name: 'CormorantGaramond', style: 'normal' },
    { key: 'CormorantGaramond-SemiBold', name: 'CormorantGaramond', style: 'semibold' },
    { key: 'CormorantGaramond-Italic', name: 'CormorantGaramond', style: 'italic' },
    { key: 'PlayfairDisplay-Bold', name: 'PlayfairDisplay', style: 'bold' },
    { key: 'PlayfairDisplay-BoldItalic', name: 'PlayfairDisplay', style: 'bolditalic' },
    { key: 'DMSans-Light', name: 'DMSans', style: 'light' },
    { key: 'DMSans-Regular', name: 'DMSans', style: 'normal' },
    { key: 'DMSans-Medium', name: 'DMSans', style: 'medium' },
    { key: 'PinyonScript-Regular', name: 'PinyonScript', style: 'normal' },
  ];

  window.WSA_FONTS = {

    registerWith: function (pdf) {
      var loaded = 0;
      MAP.forEach(function (f) {
        var b64 = DATA[f.key];
        if (!b64) return;
        var filename = f.key + '.ttf';
        pdf.addFileToVFS(filename, b64);
        pdf.addFont(filename, f.name, f.style);
        loaded++;
      });
      if (loaded === 0) console.warn('WSA_FONTS: Keine Schriften eingebettet.');
      return loaded;
    },

    status: function () {
      return MAP.map(function (f) { return { font: f.key, embedded: !!DATA[f.key] }; });
    },

    has: function (key) { return !!DATA[key]; },

    registerWithCSS: function () {
      var styleMap = {
        light:    { style: 'normal',  weight: 300 },
        normal:   { style: 'normal',  weight: 400 },
        semibold: { style: 'normal',  weight: 600 },
        italic:   { style: 'italic',  weight: 400 },
        bold:     { style: 'normal',  weight: 700 },
        medium:   { style: 'normal',  weight: 500 },
      };
      // CSS font-family names with spaces (as referenced in CSS rules)
      var cssNames = {
        CormorantGaramond: 'Cormorant Garamond',
        PinyonScript:      'Pinyon Script',
        PlayfairDisplay:   'Playfair Display',
        DMSans:            'DM Sans',
      };
      MAP.forEach(function (f) {
        var b64 = DATA[f.key];
        if (!b64) return;
        var sm = styleMap[f.style] || { style: 'normal', weight: 400 };
        var family = cssNames[f.name] || f.name;
        var css = '@font-face{font-family:"' + family + '";font-style:' + sm.style +
                  ';font-weight:' + sm.weight +
                  ';font-display:swap' +
                  ';src:url("data:font/truetype;base64,' + b64 + '") format("truetype")}';
        var el = document.createElement('style');
        el.textContent = css;
        document.head.appendChild(el);
      });
    },

    set: function (pdf, name, style) {
      var entry = null;
      for (var i = 0; i < MAP.length; i++) {
        if (MAP[i].name === name && MAP[i].style === style) { entry = MAP[i]; break; }
      }
      if (entry && DATA[entry.key]) {
        pdf.setFont(name, style);
      } else {
        var fb = { CormorantGaramond: { normal:['Times','normal'], italic:['Times','italic'], light:['Times','normal'], semibold:['Times','bold'] }, PlayfairDisplay: { bold:['Times','bold'], bolditalic:['Times','bolditalic'] }, DMSans: { normal:['Helvetica','normal'], light:['Helvetica','normal'], medium:['Helvetica','bold'] } };
        var r = ((fb[name] || {})[style]) || ['Helvetica','normal'];
        pdf.setFont(r[0], r[1]);
      }
    },

  };

})();